newrelay="""async function relayStream(r:Response,res:ServerResponse,api:'openai'|'anthropic',model:string,p:'openai'|'anthropic'|'gemini'){\n  if(p==='anthropic'&&api==='anthropic'){res.writeHead(200,{'content-type':'text/event-stream','cache-control':'no-cache'});if(r.body)for await(const c of r.body as any)res.write(Buffer.from(c));res.end();return;}\n  if(p==='openai'&&api==='anthropic'){res.writeHead(200,{'content-type':'text/event-stream','cache-control':'no-cache'});if(r.body){for await(const e of anthropicEventsFromOpenAI(r.body,model))res.write(e);}res.end();return;}\n  const raw=await r.text();let text='',input=0,output=0;\n  if(p==='gemini'){for(const x of raw.split(/\\n\\n/)){const m=/data:\\s*(\\{.*\\})/s.exec(x);if(!m)continue;try{const j=JSON.parse(m[1]);const c=isRecord(j.candidates?.[0])?j.candidates[0]:{};const co=isRecord(c.content)?c.content:{};text+=textOf(co.parts);const u=isRecord(j.usageMetadata)?j.usageMetadata:{};input=Number(u.promptTokenCount??input);output=Number(u.candidatesTokenCount??output);}catch{}}}\n  else {try{const j=JSON.parse(raw);text=textOf(j.content);const u=isRecord(j.usage)?j.usage:{};input=Number(u.input_tokens??0);output=Number(u.output_tokens??0);}catch{}}\n  res.writeHead(200,{'content-type':'text/event-stream'});\n  if(api==='openai'){const c={id:'chatcmpl-sim',object:'chat.completion.chunk',created:1767225600,model,choices:[{index:0,delta:{role:'assistant',content:text},finish_reason:'stop'}]};res.end(`data: ${JSON.stringify(c)}\\n\\ndata: ${JSON.stringify({...c,choices:[],usage:{prompt_tokens:input,completion_tokens:output,total_tokens:input+output}})}\\n\\ndata: [DONE]\\n\\n`);}\n  else res.end(`event: message_start\\ndata: ${JSON.stringify({type:'message_start',message:{id:'msg_sim',type:'message',role:'assistant',model,content:[],stop_reason:null,stop_sequence:null,usage:{input_tokens:input,output_tokens:0}}})}\\n\\nevent: content_block_start\\ndata: ${JSON.stringify({type:'content_block_start',index:0,content_block:{type:'text',text:''}})}\\n\\nevent: content_block_delta\\ndata: ${JSON.stringify({type:'content_block_delta',index:0,delta:{type:'text_delta',text}})}\\n\\nevent: content_block_stop\\ndata: ${JSON.stringify({type:'content_block_stop',index:0})}\\n\\nevent: message_delta\\ndata: ${JSON.stringify({type:'message_delta',delta:{stop_reason:'end_turn',stop_sequence:null},usage:{output_tokens:output}})}\\n\\nevent: message_stop\\ndata: ${JSON.stringify({type:'message_stop'})}\\n\\n`);\n}\n"""
